const fmt = (n, d = 0) => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
function delta(a, b, unit = '%') {
  if (unit === 'pt') { const d = a - b; if (Math.abs(d) < 0.05) return `<span class="d flat">เท่าเดิม</span>`; return `<span class="d ${d > 0 ? 'up' : 'down'}">${d > 0 ? '▲' : '▼'} ${fmt(Math.abs(d), 1)} จุด</span>`; }
  if (!b) return a ? '<span class="d flat">ใหม่</span>' : '<span class="d flat">–</span>';
  const d = ((a - b) / b) * 100;
  if (Math.abs(d) < 0.5) return `<span class="d flat">เท่าเดิม</span>`;
  return `<span class="d ${d > 0 ? 'up' : 'down'}">${d > 0 ? '▲' : '▼'} ${fmt(Math.abs(d), 0)}%</span>`;
}
const tile = (label, value, d, sub = '') => `<div class="tile"><div class="tl">${label}</div><div class="tv">${value}</div><div class="ts">${d}${sub ? ' ' + sub : ''}</div></div>`;

function chart(values) {
  const W = 700, H = 120, P = 30, n = values.length, bw = (W - P) / n;
  const bars = values.map((v, i) => {
    const h = Math.max(v > 0 ? 2 : 0, (Math.min(100, v) / 100) * (H - 26));
    const x = P + i * bw + 1.5, y = H - 16 - h;
    const day = i + 1;
    const wk = M0.set({ day }).weekday >= 6;
    return `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${(bw - 3).toFixed(1)}" height="${h.toFixed(1)}" rx="1.5" fill="${wk ? '#B08D3E' : '#D9C79B'}"/>`
      + ((day === 1 || day % 5 === 0) ? `<text x="${(x + (bw - 3) / 2).toFixed(1)}" y="${H - 3}" text-anchor="middle">${day}</text>` : '');
  }).join('');
  const grid = [0, 50, 100].map((g) => { const y = H - 16 - (g / 100) * (H - 26); return `<line x1="${P}" x2="${W}" y1="${y}" y2="${y}" stroke="#E7E1D4" stroke-width="1"/><text x="${P - 4}" y="${y + 3}" text-anchor="end">${g}%</text>`; }).join('');
  return `<svg viewBox="0 0 ${W} ${H}" width="100%" class="chart">${grid}${bars}</svg>`;
}
